<?php
global $wpdb;wp_set_current_user(1);if(DB_NAME!=='zmp66b_isolated'||$wpdb->prefix!=='z66a_'||!current_user_can('manage_options')||!ZMP_School_Email_Access::schema_is_compatible())WP_CLI::error('local preflight');
$t=strtolower(wp_generate_password(12,false,false));$users=[];$mentors=[];$schools=[];$checks=[];$rt=$wpdb->prefix.'zmp_school_email_requests';$et=$wpdb->prefix.'zmp_school_email_request_events';$mt=$wpdb->prefix.'zmp_mentors';$st=$wpdb->prefix.'zmp_mentor_schools';$pt=$wpdb->prefix.'zmp_mentor_school_profiles';$base=[(int)$wpdb->get_var("SELECT COUNT(*) FROM $rt"),(int)$wpdb->get_var("SELECT COUNT(*) FROM $et")];
$mk=static function($n,$teacher=true)use(&$users,$t){$l='zmp66_bound_'.$n.'_'.$t;$id=wp_insert_user(['user_login'=>$l,'user_pass'=>wp_generate_password(32,true,true),'user_email'=>$l.'@example.invalid','display_name'=>'Synthetic '.$n,'role'=>$teacher?'zmp_teacher':'subscriber']);if(is_wp_error($id))throw new RuntimeException('user');$id=(int)$id;$users[]=$id;if($teacher)get_user_by('id',$id)->add_role('subscriber');return $id;};
$mentor=static function($uid,$school)use(&$mentors,&$schools,$wpdb){$u=get_userdata($uid);if($wpdb->insert($wpdb->prefix.'zmp_mentors',['wp_user_id'=>$uid,'full_name'=>$u->display_name,'email'=>$u->user_email,'phone'=>'','school_name'=>$school,'municipality'=>'Skopje','region'=>'Region','login_token'=>wp_generate_password(30,false)])!==1)throw new RuntimeException('mentor');$mid=(int)$wpdb->insert_id;$mentors[$uid]=$mid;wp_set_current_user($uid);$sid=ZMP_Mentor_Schools::add_school($mid,$school,'Skopje',true);if(is_wp_error($sid))throw new RuntimeException('school');$schools[$uid]=(int)$sid;};
$count=static function()use($wpdb,$rt,$et){return [(int)$wpdb->get_var("SELECT COUNT(*) FROM $rt"),(int)$wpdb->get_var("SELECT COUNT(*) FROM $et")];};
$expect=static function($name,$res,$code)use(&$checks,$count,$base){$checks[$name]=is_wp_error($res)&&$res->get_error_code()===$code&&$count()===$base;};
