$expect('missing_contact_profile_rejected',ZMP_School_Email_Access::submit_request($r,$o,$schools[$r],'A valid reason for test'),'contact_unavailable');
$expect('unrelated_owner_school_rejected',ZMP_School_Email_Access::submit_request($r,$x,$schools[$r],'A valid reason for test'),'school_relationship_required');
$expect('non_teacher_contact_rejected',ZMP_School_Email_Access::submit_request($r,$plain,$schools[$r],'A valid reason for test'),'contact_unavailable');
$expect('unowned_school_id_rejected',ZMP_School_Email_Access::submit_request($r,$o,$schools[$x],'A valid reason for test'),'school_not_owned');
$expect('overlong_reason_rejected',ZMP_School_Email_Access::submit_request($r,$o,$schools[$r],str_repeat('x',501)),'invalid_reason');
}catch(Throwable $e){$checks['runtime_completed']=false;WP_CLI::warning('fixture setup failed: '.sanitize_key($e->getMessage()));}
