foreach($checks as$k=>$v)echo($v?'PASS ':'FAIL ').$k.PHP_EOL;$n=count(array_filter($checks,static fn($v)=>$v===true));echo 'SUMMARY '.$n.'/'.count($checks).' PASS'.PHP_EOL;if($n!==count($checks))exit(1);
